"""Every rounding rule of meterbill lives here (see docs/rounding.md)."""

from __future__ import annotations

import math
from decimal import Decimal
from fractions import Fraction

CENT = Decimal("0.01")
HALF_UP = "half_up"
HALF_EVEN = "half_even"
DOWN = "down"

_METHODS = (HALF_UP, HALF_EVEN, DOWN)


def _check(value, step, method) -> None:
    if not isinstance(value, Decimal) or not isinstance(step, Decimal):
        raise TypeError("value and step must be Decimal")
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if not step.is_finite() or step <= 0:
        raise ValueError("step must be a positive decimal")
    if not value.is_finite():
        raise ValueError("value must be finite")


def _units(value: Decimal, step: Decimal, method: str) -> int:
    """|value| / step rounded to a whole number of steps, by `method`."""
    ratio = abs(Fraction(value)) / Fraction(step)
    n = ratio.numerator // ratio.denominator
    if method == DOWN:
        return n
    twice = 2 * (ratio - n)
    if twice > 1 or (twice == 1 and (method == HALF_UP or n % 2 == 1)):
        n += 1
    return n


def _build(negative: bool, n: int, step: Decimal) -> Decimal:
    """n steps as a Decimal carrying the exponent of `step`."""
    t = step.as_tuple()
    coefficient = n * int(Decimal(step).scaleb(-t.exponent)) if False else n * _int_coefficient(t)
    digits = tuple(int(c) for c in str(coefficient))
    return Decimal((1 if negative else 0, digits, t.exponent))


def _int_coefficient(t) -> int:
    c = 0
    for d in t.digits:
        c = c * 10 + d
    return c


def round_amount(value: Decimal, step: Decimal, method: str) -> Decimal:
    _check(value, step, method)
    n = _units(value, step, method)
    return _build(value.is_signed(), n, step)


def allocate(amounts: list, step: Decimal) -> list:
    """Cut every amount down to `step`; the loss against the rounded sum goes
    on the last amount that is not zero."""
    parts = [round_amount(a, step, DOWN) for a in amounts]
    whole = round_amount(sum(amounts, Decimal("0")), step, HALF_UP)
    rest = whole - sum(parts, _build(False, 0, step))
    for i in range(len(parts) - 1, -1, -1):
        if amounts[i] != 0:
            parts[i] += rest
            break
    return parts


def legacy_cents(value: float, places: int = 2) -> float:
    scale = 10**places
    return math.floor(value * scale + 0.5) / scale


def fixed(value, places: int, method: str = HALF_EVEN) -> str:
    if method not in _METHODS:
        raise ValueError(f"unknown rounding method {method!r}")
    if isinstance(places, bool) or not isinstance(places, int) or places < 0:
        raise ValueError("places must be a non-negative integer")
    if isinstance(value, float):
        if method != HALF_EVEN:
            raise ValueError("a float is only written half to even")
        return format(value, f".{places}f")
    if not isinstance(value, Decimal):
        raise TypeError("value must be a float or a Decimal")
    step = Decimal((0, (1,), -places))
    r = round_amount(value, step, method)
    t = r.as_tuple()
    text = str(_int_coefficient(t)).rjust(places + 1, "0")
    if places:
        text = text[:-places] + "." + text[-places:]
    return ("-" if t.sign else "") + text

